INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C1','kor',2,1,'u7',1,'상황 속 말과 마음 — 발표를 앞둔 친구, 무거운 책상·줄넘기 그림에서 들은 말 때문에 상한 마음을 짐작하고 응원하거나 도와주는 말로 바꾸기',ARRAY['2국01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C2','kor',2,1,'u7',1,'고운 말과 그 까닭 — 들으면 기분 좋아지는 고운 말을 알고, 내 말 한마디로 상대의 기분과 사이가 달라지므로 늘 고운 말을 써야 함을 알기',ARRAY['2국01-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C3','kor',2,1,'u7',3,'「지우와 머리핀」 내용 — 지우가 승강기에서 주운 머리핀의 주인을 찾으려 관리 사무소에 가고 안내문을 만들어 고맙다는 쪽지를 받은 차례 정리하기',ARRAY['2국01-05']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C4','kor',2,1,'u7',3,'경험의 뜻과 경험 견주기 — 한 일·본 일·들은 일과 그때의 생각이나 느낌이 경험임을 알고, 인물의 경험과 비슷한 내 경험을 떠올려 견주어 말하기',ARRAY['2국01-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C5','kor',2,1,'u7',5,'발표할 경험 정리하기 — 가장 기억에 남는 일을 골라 언제·어디에서·무슨 일·그때의 생각이나 느낌으로 정리하기',ARRAY['2국01-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C6','kor',2,1,'u7',5,'바른 자세로 발표하고 듣기 — 듣는 사람을 바라보며·말끝을 흐리지 않고·알맞은 목소리로·바른 자세로 발표하고, 친구 발표를 끝까지 듣고 잘한 점 칭찬하기',ARRAY['2국01-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C7','kor',2,1,'u7',7,'마음을 생각하며 고운 말로 바꾸기 — 그림을 망친 만화에서 두 친구의 마음을 짐작하고, 화난 말 대신 사과와 걱정의 고운 말로 화해하기',ARRAY['2국01-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C8','kor',2,1,'u7',7,'상황에 맞는 고운 말 역할놀이 — 무거운 책 나르기·넘어진 친구·물 튀기기 상황에 맞는 고운 말을 표정·말투·몸짓과 함께 역할놀이로 주고받기',ARRAY['2국01-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C9','kor',2,1,'u7',9,'「메기야, 고마워」 내용 — 강이 넘쳐 연못에 온 메기를 물고기들이 피했다가, 물장군을 쫓아 준 메기에게 고맙다고 인사한 차례와 까닭 찾기',ARRAY['2국01-05']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C10','kor',2,1,'u7',9,'흉내 내는 말의 뜻 — 반짝반짝·슬금슬금·빙그레가 이야기 속 상황에서 어떤 모양을 나타내는지 알기',ARRAY['2국01-05']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C11','kor',2,1,'u7',9,'고운 말로 마음 전하기 — 마음을 전하고 싶은 사람, 전하고 싶은 마음과 까닭, 고운 말을 정리해 쪽지를 써서 직접 전하기',ARRAY['2국01-02']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C12','kor',2,1,'u7',12,'고운 말 놀이로 연습하기 — 고운 말 맞추기 놀이, 고양이와 쥐 고운 말 놀이, 친구에게 고운 말 놀이로 상황에 맞는 고운 말을 상냥하게 말하기',ARRAY['2국01-05']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C13','kor',2,1,'u7',12,'바른 언어 습관 — 「것 같다」를 버릇처럼 쓰지 않고 확실한 일은 자신 있게 말하기, 여러 뜻을 가진 낱말(머리·깎다) 알기(기초 다지기)',ARRAY['2국01-02']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
