INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X05','kor',2,'u7',ARRAY['K2-1-u7-C6']::text[],'바닥을 보거나 말끝을 흐리며 발표한다','바라보며, 끝까지 또렷하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
