INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X11','kor',2,'u7',ARRAY['K2-1-u7-C11']::text[],'고운 말 쪽지에 받을 사람이나 전하고 싶은 까닭을 빠뜨린다','누구에게·어떤 마음·왜') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
