INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#9','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C1',4,'essay','teacher','218쪽 그림 ㉮에서 남자아이가 여자아이에게 할 수 있는 고운 말을 쓰고, 그 말을 들은 여자아이의 마음을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C1","difficulty":4,"kind":"essay","stem":"218쪽 그림 ㉮에서 남자아이가 여자아이에게 할 수 있는 고운 말을 쓰고, 그 말을 들은 여자아이의 마음을 쓰세요.","answer_guide":{"answer":"예: 「많이 무겁지? 내가 같이 들어 줄게.」 — 고맙고 힘이 나는 마음이 들 것이다.","scoring_points":["고운 말을 썼어요","들은 사람의 마음을 썼어요"]},"explanation":["고운 말이에요.","219쪽이에요.","예시예요."],"asset":{"type":"speech","turns":[{"who":"여자아이","text":"휴, 힘들어. 많이 무겁네."},{"who":"남자아이","text":"혼자서 그것도 못 옮기니?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#10','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',4,'essay','teacher','누군가에게 고운 말을 들었던 경험과 그때의 기분을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C2","difficulty":4,"kind":"essay","stem":"누군가에게 고운 말을 들었던 경험과 그때의 기분을 쓰세요.","answer_guide":{"answer":"예: 받아쓰기를 틀려 속상할 때 짝이 「괜찮아, 다음엔 잘할 거야.」라고 해 줘서 힘이 났다.","scoring_points":["고운 말을 들었던 경험을 썼어요","그때의 기분을 썼어요"]},"explanation":["경험과 기분이에요.","219쪽이에요.","지도서 283쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#1','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C3',1,'mc','auto','지우가 승강기 안에서 발견한 것은?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":1,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"지우가 승강기 안에서 발견한 것은?","options":[{"t":"누군가 잃어버린 머리핀","correct":true},{"t":"우산","mis":"K2-1-u7-X07"},{"t":"열쇠","mis":"K2-1-u7-X07"}],"explanation":["머리핀이에요.","221쪽 (1)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["지우는 승강기에서 토끼가 그려진 머리핀을 발견했어요.","얼마 전 아끼는 우산을 잃어버려 속상했던 지우는 주인을 찾아 주고 싶었어요.","관리 사무소 소장님께 말씀드리고 「머리핀 주인을 찾습니다!」 안내문을 만들었어요.","며칠 뒤 안내문에 고맙다는 쪽지가 붙어 있었어요. 지우는 뿌듯하고 행복했어요."],"title":"『국어』 220쪽 「지우와 머리핀」(듣기 자료) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#2','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C3',1,'mc','auto','지우는 머리핀을 발견한 뒤 어떻게 했나요?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":2,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"지우는 머리핀을 발견한 뒤 어떻게 했나요?","options":[{"t":"주인을 찾아 주려고 관리 사무소 소장님을 찾아갔어요","correct":true},{"t":"자기가 가졌어요","mis":"K2-1-u7-X07"},{"t":"버렸어요","mis":"K2-1-u7-X07"}],"explanation":["주인을 찾아요.","221쪽 (2)예요.","예시 답안이에요."],"asset":{"type":"passage","lines":["지우는 승강기에서 토끼가 그려진 머리핀을 발견했어요.","얼마 전 아끼는 우산을 잃어버려 속상했던 지우는 주인을 찾아 주고 싶었어요.","관리 사무소 소장님께 말씀드리고 「머리핀 주인을 찾습니다!」 안내문을 만들었어요.","며칠 뒤 안내문에 고맙다는 쪽지가 붙어 있었어요. 지우는 뿌듯하고 행복했어요."],"title":"『국어』 220쪽 「지우와 머리핀」(듣기 자료) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
