INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#7','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',2,'match','auto','지우가 있었던 일과 생각이나 느낌을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K2-1-u7-C4","difficulty":2,"kind":"match","stem":"지우가 있었던 일과 생각이나 느낌을 이어 보세요.","pairs":[{"l":"머리핀을 주웠다","r":"주인이 속상할 것 같았다"},{"l":"안내문을 붙였다","r":"주인이 빨리 봤으면 좋겠다"},{"l":"쪽지를 받았다","r":"뿌듯하고 행복했다"}],"mis":"K2-1-u7-X04","explanation":["있었던 일과 느낌이에요.","223쪽 5번이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["지우는 승강기에서 토끼가 그려진 머리핀을 발견했어요.","얼마 전 아끼는 우산을 잃어버려 속상했던 지우는 주인을 찾아 주고 싶었어요.","관리 사무소 소장님께 말씀드리고 「머리핀 주인을 찾습니다!」 안내문을 만들었어요.","며칠 뒤 안내문에 고맙다는 쪽지가 붙어 있었어요. 지우는 뿌듯하고 행복했어요."],"title":"『국어』 220쪽 「지우와 머리핀」(듣기 자료) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
