INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#9','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',2,'mc','auto','내가 직접 한 일이 떠오르지 않을 때 말할 수 있는 것은?',ARRAY['K2-1-u7-X04','K2-1-u7-X07']::text[],false,'{"seq":9,"concept":"K2-1-u7-C4","difficulty":2,"kind":"mc","stem":"내가 직접 한 일이 떠오르지 않을 때 말할 수 있는 것은?","options":[{"t":"보거나 들었던 일","correct":true},{"t":"아무것도 말하지 않아요","mis":"K2-1-u7-X04"},{"t":"지어낸 일","mis":"K2-1-u7-X07"}],"explanation":["본 일·들은 일이에요.","222쪽 도우미예요.","경험이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#10','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',3,'mc','auto','지우의 경험에 대한 생각을 알맞게 말한 것은?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":10,"concept":"K2-1-u7-C4","difficulty":3,"kind":"mc","stem":"지우의 경험에 대한 생각을 알맞게 말한 것은?","options":[{"t":"「떨어진 필통을 그냥 지나친 적이 있는데, 다음엔 지우처럼 주인을 찾아 줄 거야.」","correct":true},{"t":"「지우는 괜히 힘들게 했어.」","mis":"K2-1-u7-X07"},{"t":"「머리핀은 내가 가지면 돼.」","mis":"K2-1-u7-X07"}],"explanation":["견주어 말해요.","223쪽 6번이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["지우는 승강기에서 토끼가 그려진 머리핀을 발견했어요.","얼마 전 아끼는 우산을 잃어버려 속상했던 지우는 주인을 찾아 주고 싶었어요.","관리 사무소 소장님께 말씀드리고 「머리핀 주인을 찾습니다!」 안내문을 만들었어요.","며칠 뒤 안내문에 고맙다는 쪽지가 붙어 있었어요. 지우는 뿌듯하고 행복했어요."],"title":"『국어』 220쪽 「지우와 머리핀」(듣기 자료) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
