INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#6','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',3,'mc','auto','「지난 주말, 도서관에서 공룡 책을 빌렸다.」에 더하면 좋은 내용은?',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":6,"concept":"K2-1-u7-C5","difficulty":3,"kind":"mc","stem":"「지난 주말, 도서관에서 공룡 책을 빌렸다.」에 더하면 좋은 내용은?","options":[{"t":"「공룡 이름을 많이 알게 되어 신기했다.」처럼 생각이나 느낌","correct":true},{"t":"「도서관은 3층 건물이다.」","mis":"K2-1-u7-X03"},{"t":"「친구는 수영을 했다.」","mis":"K2-1-u7-X03"}],"explanation":["생각이나 느낌이에요.","225쪽이에요.","정리하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#7','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C6',3,'mc','auto','발표 자기 평가에서 확인할 내용이 아닌 것은?',ARRAY['K2-1-u7-X05']::text[],false,'{"seq":7,"concept":"K2-1-u7-C6","difficulty":3,"kind":"mc","stem":"발표 자기 평가에서 확인할 내용이 아닌 것은?","options":[{"t":"가장 비싼 물건을 이야기했나요?","correct":true},{"t":"듣는 사람을 바라보며 말했나요?","mis":"K2-1-u7-X05"},{"t":"바른 자세로 말했나요?","mis":"K2-1-u7-X05"}],"explanation":["관계없어요.","227쪽이에요.","점검하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#8','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C4',4,'sa','auto','한 일·본 일·들은 일과 그때의 생각이나 느낌을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u7-C4","difficulty":4,"kind":"sa","stem":"한 일·본 일·들은 일과 그때의 생각이나 느낌을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["경험"],"explanation":["경험이에요.","지도서 290쪽이에요.","정리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#9','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',4,'essay','teacher','지난 주말에 겪은 일 가운데 가장 기억에 남는 일을 「언제·어디에서·무슨 일·생각이나 느낌」으로 정리해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"지난 주말에 겪은 일 가운데 가장 기억에 남는 일을 「언제·어디에서·무슨 일·생각이나 느낌」으로 정리해 쓰세요.","answer_guide":{"answer":"예: 지난 일요일, 할머니 댁 텃밭에서 고구마를 캤다. 커다란 고구마가 나와서 정말 신기하고 뿌듯했다.","scoring_points":["언제·어디에서를 썼어요","무슨 일과 생각이나 느낌을 썼어요"]},"explanation":["발표 준비예요.","225쪽이에요.","정리하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#10','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C6',4,'essay','teacher','친구들 앞에서 발표할 때 지킬 바른 자세 두 가지와, 친구의 발표를 들을 때 지킬 점 한 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C6","difficulty":4,"kind":"essay","stem":"친구들 앞에서 발표할 때 지킬 바른 자세 두 가지와, 친구의 발표를 들을 때 지킬 점 한 가지를 쓰세요.","answer_guide":{"answer":"예: 듣는 사람을 바라보며 말한다. 말끝을 흐리지 않는다. / 친구의 발표를 끝까지 듣고 잘한 점을 칭찬한다.","scoring_points":["발표 자세 두 가지를 썼어요","듣는 자세를 썼어요"]},"explanation":["발표와 듣기예요.","227쪽이에요.","점검하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#1','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C7',1,'mc','auto','그림을 망친 남자아이의 마음은?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":1,"concept":"K2-1-u7-C7","difficulty":1,"kind":"mc","stem":"그림을 망친 남자아이의 마음은?","options":[{"t":"정성껏 그린 그림을 망쳐서 화가 난 마음","correct":true},{"t":"기쁘고 신나는 마음","mis":"K2-1-u7-X01"},{"t":"졸린 마음","mis":"K2-1-u7-X01"}],"explanation":["화가 났어요.","228쪽이에요.","지도서 294쪽이에요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"너 때문에 그림을 망쳤잖아. 앞을 잘 보고 다녀야지."},{"who":"여자아이","text":"그림을 망쳐서 화가 많이 났구나. 미안해. 가방이 걸려 있는 줄 몰랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
