INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#8','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C7',4,'sa','auto','남자아이의 그림을 망치게 된 것은 여자아이가 무엇에 걸려 넘어져서인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u7-C7","difficulty":4,"kind":"sa","stem":"남자아이의 그림을 망치게 된 것은 여자아이가 무엇에 걸려 넘어져서인가요? 두 글자로 쓰세요.","answer":["가방"],"explanation":["가방이에요.","228쪽이에요.","만화예요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"너 때문에 그림을 망쳤잖아. 앞을 잘 보고 다녀야지."},{"who":"여자아이","text":"그림을 망쳐서 화가 많이 났구나. 미안해. 가방이 걸려 있는 줄 몰랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#9','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C7',4,'essay','teacher','229쪽 3번 — 만화 속 두 친구가 사이좋게 지내려면 서로에게 어떻게 말하면 좋을지 남자아이의 말과 여자아이의 말을 하나씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C7","difficulty":4,"kind":"essay","stem":"229쪽 3번 — 만화 속 두 친구가 사이좋게 지내려면 서로에게 어떻게 말하면 좋을지 남자아이의 말과 여자아이의 말을 하나씩 쓰세요.","answer_guide":{"answer":"예: 남자아이 — 「다친 데는 괜찮니? 화내서 미안해.」 / 여자아이 — 「사과해 줘서 고마워. 나도 미안해.」","scoring_points":["남자아이의 고운 말을 썼어요","여자아이의 고운 말을 썼어요"]},"explanation":["화해의 말이에요.","229쪽이에요.","지도서 295쪽이에요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"너 때문에 그림을 망쳤잖아. 앞을 잘 보고 다녀야지."},{"who":"여자아이","text":"그림을 망쳐서 화가 많이 났구나. 미안해. 가방이 걸려 있는 줄 몰랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
