INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#7','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C11',3,'mc','auto','붕어와 잉어처럼 도움을 받았을 때 알맞은 말은?',ARRAY['K2-1-u7-X01','K2-1-u7-X11']::text[],false,'{"seq":7,"concept":"K2-1-u7-C11","difficulty":3,"kind":"mc","stem":"붕어와 잉어처럼 도움을 받았을 때 알맞은 말은?","options":[{"t":"「도와줘서 정말 고마워.」","correct":true},{"t":"「원래 도와줘야지.」","mis":"K2-1-u7-X01"},{"t":"아무 말도 하지 않아요","mis":"K2-1-u7-X11"}],"explanation":["고마움을 전해요.","235쪽이에요.","고운 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#8','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',4,'sa','auto','붕어와 잉어의 몸에 달라붙은 벌레 이름을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u7-C9","difficulty":4,"kind":"sa","stem":"붕어와 잉어의 몸에 달라붙은 벌레 이름을 세 글자로 쓰세요.","answer":["물장군"],"explanation":["물장군이에요.","234쪽이에요.","이야기예요."],"asset":{"type":"scene","icon":"🐟","text":"「메기야, 고마워」(홍은순) — 강이 넘쳐 연못에 온 메기를 피하던 물고기들이, 물장군을 쫓아 준 메기에게 고맙다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#9','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C11',4,'essay','teacher','239쪽 — 고운 말로 마음을 전하고 싶은 사람에게 쪽지를 쓰세요. (받을 사람, 전하고 싶은 마음과 까닭, 고운 말)','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C11","difficulty":4,"kind":"essay","stem":"239쪽 — 고운 말로 마음을 전하고 싶은 사람에게 쪽지를 쓰세요. (받을 사람, 전하고 싶은 마음과 까닭, 고운 말)","answer_guide":{"answer":"예: 담임 선생님께 — 모르는 것도 자세히 알려 주셔서 감사합니다. 선생님 덕분에 학교에 오는 게 정말 즐거워요.","scoring_points":["받을 사람을 썼어요","마음과 까닭을 고운 말로 썼어요"]},"explanation":["고운 말 쪽지예요.","239쪽이에요.","붙임 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#10','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C11',4,'essay','teacher','238쪽 — 친구에게 도움을 받았던 경험을 쓰고, 그 친구에게 전하고 싶은 고운 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C11","difficulty":4,"kind":"essay","stem":"238쪽 — 친구에게 도움을 받았던 경험을 쓰고, 그 친구에게 전하고 싶은 고운 말을 쓰세요.","answer_guide":{"answer":"예: 운동장에서 잃어버린 줄넘기를 민재가 함께 찾아 주었다. — 「민재야, 도와줘서 정말 고마워.」","scoring_points":["도움을 받은 경험을 썼어요","전하고 싶은 고운 말을 썼어요"]},"explanation":["자신과 관련짓기예요.","238쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
