INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#2','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C12',1,'mc','auto','240쪽 보기에 있는 고운 말은?',ARRAY['K2-1-u7-X09']::text[],false,'{"seq":2,"concept":"K2-1-u7-C12","difficulty":1,"kind":"mc","stem":"240쪽 보기에 있는 고운 말은?","options":[{"t":"「넌 소중한 친구야.」","correct":true},{"t":"「너 때문이야.」","mis":"K2-1-u7-X09"},{"t":"「그것도 못하니?」","mis":"K2-1-u7-X09"}],"explanation":["고운 말이에요.","240쪽이에요.","보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#3','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C13',1,'mc','auto','「네, 잘 다녀온 것 같아요.」를 바르게 고친 것은?',ARRAY['K2-1-u7-X12']::text[],false,'{"seq":3,"concept":"K2-1-u7-C13","difficulty":1,"kind":"mc","stem":"「네, 잘 다녀온 것 같아요.」를 바르게 고친 것은?","options":[{"t":"「네, 잘 다녀왔어요.」","correct":true},{"t":"「네, 다녀온 것 같은 것 같아요.」","mis":"K2-1-u7-X12"},{"t":"「네, 몰라요.」","mis":"K2-1-u7-X12"}],"explanation":["자신 있게요.","244쪽 예시예요.","기초 다지기예요."],"asset":{"type":"speech","turns":[{"who":"엄마","text":"수지야, 오늘 학교 잘 다녀왔니?"},{"who":"수지","text":"네, 잘 다녀온 것 같아요."},{"who":"엄마","text":"왜 자꾸 말끝에 「같아요」를 붙이니?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#4','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C3',1,'mc','auto','다빈이가 들었던 고운 말은?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":4,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"다빈이가 들었던 고운 말은?","options":[{"t":"「금메달 딴 거 축하해.」","correct":true},{"t":"「운이 좋았네.」","mis":"K2-1-u7-X07"},{"t":"「다음엔 내가 이겨.」","mis":"K2-1-u7-X07"}],"explanation":["축하해요.","242쪽 (2)예요.","예시 답안이에요."],"asset":{"type":"passage","lines":["지난 토요일에 열린 초등학교 태권도 대회에서 금메달을 땄다.","결승전에서 만난 상대는 같은 체육관에 다니는 은지였다.","경기가 끝나고 은지는 내 등을 토닥이면서 「금메달 딴 거 축하해.」라고 말해 주었다.","은지의 마음이 느껴져 정말 고마웠고 기분이 좋았다."],"title":"『국어』 242쪽 다빈이가 쓴 글 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
