INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#7','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C12',3,'mc','auto','고운 말 작품을 알림판에 붙여 두면 좋은 점은?',ARRAY['K2-1-u7-X14']::text[],false,'{"seq":7,"concept":"K2-1-u7-C12","difficulty":3,"kind":"mc","stem":"고운 말 작품을 알림판에 붙여 두면 좋은 점은?","options":[{"t":"매일 보며 고운 말이 자연스럽게 나오게 돼요","correct":true},{"t":"교실이 좁아져요","mis":"K2-1-u7-X14"},{"t":"고운 말을 안 해도 돼요","mis":"K2-1-u7-X14"}],"explanation":["자연스럽게요.","지도서 305쪽이에요.","정리하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#8','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C13',4,'sa','auto','수지가 말끝마다 버릇처럼 붙인 말을 쓰세요. (「○ ○○」)','{}'::text[],false,'{"seq":8,"concept":"K2-1-u7-C13","difficulty":4,"kind":"sa","stem":"수지가 말끝마다 버릇처럼 붙인 말을 쓰세요. (「○ ○○」)","answer":["것 같아요","것같아요","같아요"],"explanation":["것 같아요예요.","244쪽이에요.","기초 다지기예요."],"asset":{"type":"speech","turns":[{"who":"엄마","text":"수지야, 오늘 학교 잘 다녀왔니?"},{"who":"수지","text":"네, 잘 다녀온 것 같아요."},{"who":"엄마","text":"왜 자꾸 말끝에 「같아요」를 붙이니?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#9','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C12',4,'essay','teacher','240쪽 보기의 고운 말 가운데 내가 가장 듣고 싶은 말을 하나 고르고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C12","difficulty":4,"kind":"essay","stem":"240쪽 보기의 고운 말 가운데 내가 가장 듣고 싶은 말을 하나 고르고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「너를 응원할게.」 — 줄넘기 대회를 앞두고 떨릴 때 이 말을 들으면 힘이 날 것 같아서","scoring_points":["고운 말을 골랐어요","까닭을 썼어요"]},"explanation":["듣고 싶은 말이에요.","240쪽이에요.","정리하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#10','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C3',4,'essay','teacher','242쪽 — 다빈이처럼 누군가에게 축하나 응원의 말을 들었던 경험과 그때의 기분을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C3","difficulty":4,"kind":"essay","stem":"242쪽 — 다빈이처럼 누군가에게 축하나 응원의 말을 들었던 경험과 그때의 기분을 쓰세요.","answer_guide":{"answer":"예: 그림 대회에서 상을 받았을 때 친구가 「정말 멋지다!」라고 해 줘서 뿌듯하고 고마웠다.","scoring_points":["경험을 썼어요","그때의 기분을 썼어요"]},"explanation":["경험과 느낌이에요.","242쪽이에요.","정리하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
