INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#2','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C2',1,'mc','auto','들으면 기분이 좋아지는 고운 말은?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":2,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"들으면 기분이 좋아지는 고운 말은?","options":[{"t":"「도와줘서 고마워.」","correct":true},{"t":"「그것도 못하니?」","mis":"K2-1-u7-X01"},{"t":"「네 탓이야.」","mis":"K2-1-u7-X01"}],"explanation":["고운 말이에요.","240쪽이에요.","보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#3','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C3',1,'mc','auto','지우가 승강기에서 발견한 것은?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"지우가 승강기에서 발견한 것은?","options":[{"t":"머리핀","correct":true},{"t":"우산","mis":"K2-1-u7-X07"},{"t":"열쇠","mis":"K2-1-u7-X07"}],"explanation":["머리핀이에요.","221쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["지우는 승강기에서 토끼가 그려진 머리핀을 발견했어요.","얼마 전 아끼는 우산을 잃어버려 속상했던 지우는 주인을 찾아 주고 싶었어요.","관리 사무소 소장님께 말씀드리고 「머리핀 주인을 찾습니다!」 안내문을 만들었어요.","며칠 뒤 안내문에 고맙다는 쪽지가 붙어 있었어요. 지우는 뿌듯하고 행복했어요."],"title":"『국어』 220쪽 「지우와 머리핀」(듣기 자료) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
