INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#5','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C7',1,'mc','auto','그림을 망친 남자아이의 마음은?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":5,"concept":"K2-1-u7-C7","difficulty":1,"kind":"mc","stem":"그림을 망친 남자아이의 마음은?","options":[{"t":"화가 난 마음","correct":true},{"t":"기쁜 마음","mis":"K2-1-u7-X01"},{"t":"졸린 마음","mis":"K2-1-u7-X01"}],"explanation":["화가 났어요.","228쪽이에요.","만화예요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"너 때문에 그림을 망쳤잖아. 앞을 잘 보고 다녀야지."},{"who":"여자아이","text":"그림을 망쳐서 화가 많이 났구나. 미안해. 가방이 걸려 있는 줄 몰랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
