INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#8','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C3',1,'mc','auto','다빈이가 들었던 고운 말은?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":8,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"다빈이가 들었던 고운 말은?","options":[{"t":"「금메달 딴 거 축하해.」","correct":true},{"t":"「운이 좋았네.」","mis":"K2-1-u7-X07"},{"t":"「다음엔 내가 이겨.」","mis":"K2-1-u7-X07"}],"explanation":["축하해요.","242쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["지난 토요일에 열린 초등학교 태권도 대회에서 금메달을 땄다.","결승전에서 만난 상대는 같은 체육관에 다니는 은지였다.","경기가 끝나고 은지는 내 등을 토닥이면서 「금메달 딴 거 축하해.」라고 말해 주었다.","은지의 마음이 느껴져 정말 고마웠고 기분이 좋았다."],"title":"『국어』 242쪽 다빈이가 쓴 글 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
