INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#14','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C12',2,'mc','auto','고운 말을 소리 내어 말할 때 알맞은 것은?',ARRAY['K2-1-u7-X13']::text[],false,'{"seq":14,"concept":"K2-1-u7-C12","difficulty":2,"kind":"mc","stem":"고운 말을 소리 내어 말할 때 알맞은 것은?","options":[{"t":"상냥한 목소리로 말해요","correct":true},{"t":"웅얼거려요","mis":"K2-1-u7-X13"},{"t":"화난 목소리로 말해요","mis":"K2-1-u7-X13"}],"explanation":["상냥하게요.","지도서 305쪽이에요.","정리하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#15','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C5',2,'mc','auto','발표 정리 물음으로 알맞지 않은 것은?',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":15,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표 정리 물음으로 알맞지 않은 것은?","options":[{"t":"「친구의 키는 얼마인가요?」","correct":true},{"t":"「무슨 일을 경험했나요?」","mis":"K2-1-u7-X03"},{"t":"「생각이나 느낌은 어떠했나요?」","mis":"K2-1-u7-X03"}],"explanation":["관계없어요.","225쪽이에요.","정리하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#16','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C4',2,'match','auto','지우가 있었던 일과 생각이나 느낌을 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u7-C4","difficulty":2,"kind":"match","stem":"지우가 있었던 일과 생각이나 느낌을 이어 보세요.","pairs":[{"l":"머리핀을 주웠다","r":"주인이 속상할 것 같았다"},{"l":"안내문을 붙였다","r":"주인이 빨리 봤으면 좋겠다"},{"l":"쪽지를 받았다","r":"뿌듯하고 행복했다"}],"mis":"K2-1-u7-X04","explanation":["경험이에요.","223쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["지우는 승강기에서 토끼가 그려진 머리핀을 발견했어요.","얼마 전 아끼는 우산을 잃어버려 속상했던 지우는 주인을 찾아 주고 싶었어요.","관리 사무소 소장님께 말씀드리고 「머리핀 주인을 찾습니다!」 안내문을 만들었어요.","며칠 뒤 안내문에 고맙다는 쪽지가 붙어 있었어요. 지우는 뿌듯하고 행복했어요."],"title":"『국어』 220쪽 「지우와 머리핀」(듣기 자료) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
