INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#19','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C4',3,'ox','auto','텔레비전에서 펭귄을 본 일은 직접 한 일이 아니므로 경험이 아니다.',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":19,"concept":"K2-1-u7-C4","difficulty":3,"kind":"ox","stem":"텔레비전에서 펭귄을 본 일은 직접 한 일이 아니므로 경험이 아니다.","answer":"X","reason_options":[{"t":"본 일과 들은 일도 그때의 생각이나 느낌과 함께 경험이 되어서","correct":true},{"t":"경험은 직접 한 일만이라서","mis":"K2-1-u7-X04"}],"mis":"K2-1-u7-X04","explanation":["본 일도 경험이에요.","224쪽이에요.","지도서 289쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
