INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#21','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C7',3,'mc','auto','만화에서 처음 남자아이의 말이 친구의 마음을 상하게 한 까닭은?',ARRAY['K2-1-u7-X05','K2-1-u7-X01']::text[],false,'{"seq":21,"concept":"K2-1-u7-C7","difficulty":3,"kind":"mc","stem":"만화에서 처음 남자아이의 말이 친구의 마음을 상하게 한 까닭은?","options":[{"t":"상대의 상황을 생각하지 않고 화난 마음대로 말해서","correct":true},{"t":"목소리가 작아서","mis":"K2-1-u7-X05"},{"t":"그림이 예뻐서","mis":"K2-1-u7-X01"}],"explanation":["자기 기분대로요.","228쪽이에요.","지도서 294쪽이에요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"너 때문에 그림을 망쳤잖아. 앞을 잘 보고 다녀야지."},{"who":"여자아이","text":"그림을 망쳐서 화가 많이 났구나. 미안해. 가방이 걸려 있는 줄 몰랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#22','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C9',3,'mc','auto','「메기야, 고마워」를 읽고 알 수 있는 것은?',ARRAY['K2-1-u7-X02','K2-1-u7-X01']::text[],false,'{"seq":22,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"「메기야, 고마워」를 읽고 알 수 있는 것은?","options":[{"t":"겉모습으로 판단하지 않고 고운 말로 마음을 나누면 친해질 수 있어요","correct":true},{"t":"겉모습이 무서우면 피해야 해요","mis":"K2-1-u7-X02"},{"t":"도움은 받기만 하면 돼요","mis":"K2-1-u7-X01"}],"explanation":["마음을 나눠요.","지도서 298쪽이에요.","유의점이에요."],"asset":{"type":"scene","icon":"🐟","text":"「메기야, 고마워」(홍은순) — 강이 넘쳐 연못에 온 메기를 피하던 물고기들이, 물장군을 쫓아 준 메기에게 고맙다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#23','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C4',4,'sa','auto','한 일·본 일·들은 일과 그때의 생각이나 느낌을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u7-C4","difficulty":4,"kind":"sa","stem":"한 일·본 일·들은 일과 그때의 생각이나 느낌을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["경험"],"explanation":["경험이에요.","지도서 290쪽이에요.","정리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#24','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C5',4,'essay','teacher','지도서 310~311쪽 평가 — 2학년이 되고 가장 기억에 남는 경험을 「언제·어디에서·경험한 일·생각이나 느낌」으로 정리해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"지도서 310~311쪽 평가 — 2학년이 되고 가장 기억에 남는 경험을 「언제·어디에서·경험한 일·생각이나 느낌」으로 정리해 쓰세요.","answer_guide":{"answer":"예: 4월에 학교 운동장에서 열린 운동회에서 이어달리기 선수로 뛰었다. 떨렸지만 끝까지 달려서 뿌듯했다.","scoring_points":["언제·어디에서·경험한 일을 썼어요","생각이나 느낌을 썼어요"]},"explanation":["평가 자료 1이에요.","지도서 311쪽이에요.","경험 발표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#25','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C8',4,'essay','teacher','지도서 312~313쪽 평가 — 넘어져 다친 친구에게 할 수 있는 고운 말과 그 말을 들은 친구의 마음을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u7-C8","difficulty":4,"kind":"essay","stem":"지도서 312~313쪽 평가 — 넘어져 다친 친구에게 할 수 있는 고운 말과 그 말을 들은 친구의 마음을 쓰세요.","answer_guide":{"answer":"예: 「괜찮아? 많이 아프겠다. 보건실에 같이 가 줄게.」 — 걱정해 주어서 고맙고 마음이 놓일 것이다.","scoring_points":["상황에 맞는 고운 말을 썼어요","들은 친구의 마음을 썼어요"]},"explanation":["평가 자료 2예요.","지도서 313쪽이에요.","고운 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#1','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C1',1,'mc','auto','「혼자서 그것도 못 옮기니?」를 들은 친구의 마음은?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":1,"concept":"K2-1-u7-C1","difficulty":1,"kind":"mc","stem":"「혼자서 그것도 못 옮기니?」를 들은 친구의 마음은?","options":[{"t":"속상하고 서운한 마음","correct":true},{"t":"기쁜 마음","mis":"K2-1-u7-X01"},{"t":"뿌듯한 마음","mis":"K2-1-u7-X01"}],"explanation":["속상해요.","218쪽이에요.","예시예요."],"asset":{"type":"speech","turns":[{"who":"여자아이","text":"휴, 힘들어. 많이 무겁네."},{"who":"남자아이","text":"혼자서 그것도 못 옮기니?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#2','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C2',1,'mc','auto','들으면 기분이 좋아지는 고운 말은?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":2,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"들으면 기분이 좋아지는 고운 말은?","options":[{"t":"「너도 할 수 있어.」","correct":true},{"t":"「저리 가.」","mis":"K2-1-u7-X01"},{"t":"「몰라.」","mis":"K2-1-u7-X01"}],"explanation":["고운 말이에요.","240쪽이에요.","보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#3','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C3',1,'mc','auto','지우가 찾아간 곳은?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"지우가 찾아간 곳은?","options":[{"t":"아파트 관리 사무소","correct":true},{"t":"문구점","mis":"K2-1-u7-X07"},{"t":"학교","mis":"K2-1-u7-X07"}],"explanation":["관리 사무소예요.","221쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["지우는 승강기에서 토끼가 그려진 머리핀을 발견했어요.","얼마 전 아끼는 우산을 잃어버려 속상했던 지우는 주인을 찾아 주고 싶었어요.","관리 사무소 소장님께 말씀드리고 「머리핀 주인을 찾습니다!」 안내문을 만들었어요.","며칠 뒤 안내문에 고맙다는 쪽지가 붙어 있었어요. 지우는 뿌듯하고 행복했어요."],"title":"『국어』 220쪽 「지우와 머리핀」(듣기 자료) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
