INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#5','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C8',1,'mc','auto','넘어져 다친 친구에게 하는 고운 말은?',ARRAY['K2-1-u7-X09','K2-1-u7-X01']::text[],false,'{"seq":5,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"넘어져 다친 친구에게 하는 고운 말은?","options":[{"t":"「괜찮아? 보건실에 같이 가 줄게.」","correct":true},{"t":"「조심 좀 하지.」","mis":"K2-1-u7-X09"},{"t":"「나는 바빠.」","mis":"K2-1-u7-X01"}],"explanation":["걱정해요.","230쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#6','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C9',1,'mc','auto','붕어와 잉어 몸에 달라붙은 것은?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":6,"concept":"K2-1-u7-C9","difficulty":1,"kind":"mc","stem":"붕어와 잉어 몸에 달라붙은 것은?","options":[{"t":"물장군","correct":true},{"t":"개구리","mis":"K2-1-u7-X07"},{"t":"달팽이","mis":"K2-1-u7-X07"}],"explanation":["물장군이에요.","234쪽이에요.","이야기예요."],"asset":{"type":"scene","icon":"🐟","text":"「메기야, 고마워」(홍은순) — 강이 넘쳐 연못에 온 메기를 피하던 물고기들이, 물장군을 쫓아 준 메기에게 고맙다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#7','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C12',1,'mc','auto','240쪽 보기에 있는 고운 말은?',ARRAY['K2-1-u7-X09']::text[],false,'{"seq":7,"concept":"K2-1-u7-C12","difficulty":1,"kind":"mc","stem":"240쪽 보기에 있는 고운 말은?","options":[{"t":"「넌 소중한 친구야.」","correct":true},{"t":"「너 때문이야.」","mis":"K2-1-u7-X09"},{"t":"「그것도 못하니?」","mis":"K2-1-u7-X09"}],"explanation":["고운 말이에요.","240쪽이에요.","보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#8','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C3',1,'mc','auto','다빈이가 금메달을 딴 대회는?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":8,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"다빈이가 금메달을 딴 대회는?","options":[{"t":"태권도 대회","correct":true},{"t":"수영 대회","mis":"K2-1-u7-X07"},{"t":"달리기 대회","mis":"K2-1-u7-X07"}],"explanation":["태권도예요.","242쪽이에요.","다빈이 글이에요."],"asset":{"type":"passage","lines":["지난 토요일에 열린 초등학교 태권도 대회에서 금메달을 땄다.","결승전에서 만난 상대는 같은 체육관에 다니는 은지였다.","경기가 끝나고 은지는 내 등을 토닥이면서 「금메달 딴 거 축하해.」라고 말해 주었다.","은지의 마음이 느껴져 정말 고마웠고 기분이 좋았다."],"title":"『국어』 242쪽 다빈이가 쓴 글 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#9','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C1',2,'mc','auto','줄넘기가 잘 안되는 친구에게 하면 좋은 말은?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":9,"concept":"K2-1-u7-C1","difficulty":2,"kind":"mc","stem":"줄넘기가 잘 안되는 친구에게 하면 좋은 말은?","options":[{"t":"「괜찮아, 천천히 다시 해 보자.」","correct":true},{"t":"「넌 그것도 못하니?」","mis":"K2-1-u7-X01"},{"t":"「저리 비켜.」","mis":"K2-1-u7-X01"}],"explanation":["격려해요.","219쪽이에요.","고운 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#10','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C3',2,'mc','auto','「지우와 머리핀」을 차례대로 정리한 것은?',ARRAY['K2-1-u7-X15']::text[],false,'{"seq":10,"concept":"K2-1-u7-C3","difficulty":2,"kind":"mc","stem":"「지우와 머리핀」을 차례대로 정리한 것은?","options":[{"t":"머리핀을 주움 → 안내문을 만듦 → 쪽지를 받음","correct":true},{"t":"쪽지를 받음 → 머리핀을 주움 → 안내문","mis":"K2-1-u7-X15"},{"t":"안내문 → 머리핀을 버림","mis":"K2-1-u7-X15"}],"explanation":["차례예요.","221쪽이에요.","붙임 5예요."],"asset":{"type":"passage","lines":["지우는 승강기에서 토끼가 그려진 머리핀을 발견했어요.","얼마 전 아끼는 우산을 잃어버려 속상했던 지우는 주인을 찾아 주고 싶었어요.","관리 사무소 소장님께 말씀드리고 「머리핀 주인을 찾습니다!」 안내문을 만들었어요.","며칠 뒤 안내문에 고맙다는 쪽지가 붙어 있었어요. 지우는 뿌듯하고 행복했어요."],"title":"『국어』 220쪽 「지우와 머리핀」(듣기 자료) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#11','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C6',2,'mc','auto','말끝을 흐리지 않고 말한 것은?',ARRAY['K2-1-u7-X05']::text[],false,'{"seq":11,"concept":"K2-1-u7-C6","difficulty":2,"kind":"mc","stem":"말끝을 흐리지 않고 말한 것은?","options":[{"t":"「…자전거를 탔습니다. 정말 즐거웠습니다.」","correct":true},{"t":"「…탔는데…… 그래서……」","mis":"K2-1-u7-X05"},{"t":"「…음…… 그냥요.」","mis":"K2-1-u7-X05"}],"explanation":["또렷하게요.","227쪽이에요.","점검하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#12','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C7',2,'mc','auto','사과를 들은 여자아이가 할 말은?',ARRAY['K2-1-u7-X08']::text[],false,'{"seq":12,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"사과를 들은 여자아이가 할 말은?","options":[{"t":"「먼저 사과해 주어서 고마워. 나도 미안해.」","correct":true},{"t":"「흥, 이제 와서?」","mis":"K2-1-u7-X08"},{"t":"「네 가방 때문이야.」","mis":"K2-1-u7-X08"}],"explanation":["고마워해요.","229쪽이에요.","지도서 295쪽이에요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"너 때문에 그림을 망쳤잖아. 앞을 잘 보고 다녀야지."},{"who":"여자아이","text":"그림을 망쳐서 화가 많이 났구나. 미안해. 가방이 걸려 있는 줄 몰랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#13','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C9',2,'mc','auto','물고기들이 처음 메기를 피한 까닭은?',ARRAY['K2-1-u7-X02','K2-1-u7-X07']::text[],false,'{"seq":13,"concept":"K2-1-u7-C9","difficulty":2,"kind":"mc","stem":"물고기들이 처음 메기를 피한 까닭은?","options":[{"t":"험상궂은 겉모습을 보고 겁이 나서","correct":true},{"t":"메기가 화를 내서","mis":"K2-1-u7-X02"},{"t":"메기가 물장군을 데려와서","mis":"K2-1-u7-X07"}],"explanation":["겉모습이에요.","233쪽이에요.","이야기예요."],"asset":{"type":"scene","icon":"🐟","text":"「메기야, 고마워」(홍은순) — 강이 넘쳐 연못에 온 메기를 피하던 물고기들이, 물장군을 쫓아 준 메기에게 고맙다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#14','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C13',2,'mc','auto','「것 같다」를 알맞게 쓴 문장은?',ARRAY['K2-1-u7-X12']::text[],false,'{"seq":14,"concept":"K2-1-u7-C13","difficulty":2,"kind":"mc","stem":"「것 같다」를 알맞게 쓴 문장은?","options":[{"t":"「하늘이 흐려서 비가 올 것 같아.」","correct":true},{"t":"「장미꽃이 예쁜 것 같아요.」(예쁘다고 느낄 때)","mis":"K2-1-u7-X12"},{"t":"「학교에 다녀온 것 같아요.」","mis":"K2-1-u7-X12"}],"explanation":["짐작할 때요.","지도서 308쪽이에요.","기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#15','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C5',2,'mc','auto','「지난 주말, 도서관에서 공룡 책을 빌렸다.」에 더하면 좋은 것은?',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":15,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"「지난 주말, 도서관에서 공룡 책을 빌렸다.」에 더하면 좋은 것은?","options":[{"t":"「공룡 이름을 많이 알게 되어 신기했다.」","correct":true},{"t":"「도서관은 3층이다.」","mis":"K2-1-u7-X03"},{"t":"「친구는 수영을 했다.」","mis":"K2-1-u7-X03"}],"explanation":["생각이나 느낌이에요.","225쪽이에요.","정리하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#16','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C8',2,'match','auto','상황과 고운 말을 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u7-C8","difficulty":2,"kind":"match","stem":"상황과 고운 말을 이어 보세요.","pairs":[{"l":"무거운 책을 나르는 친구","r":"「나눠서 들자.」"},{"l":"넘어져 다친 친구","r":"「보건실에 같이 가 줄게.」"},{"l":"물을 튀기는 친구","r":"「조심해 주면 좋겠어.」"}],"mis":"K2-1-u7-X09","explanation":["상황에 맞는 말이에요.","230쪽이에요.","역할놀이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
