INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#19','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C2',3,'ox','auto','친한 친구에게는 고운 말을 쓰지 않아도 된다.',ARRAY['K2-1-u7-X14']::text[],false,'{"seq":19,"concept":"K2-1-u7-C2","difficulty":3,"kind":"ox","stem":"친한 친구에게는 고운 말을 쓰지 않아도 된다.","answer":"X","reason_options":[{"t":"친한 사이일수록 고운 말을 써야 서로의 마음이 상하지 않아서","correct":true},{"t":"친구는 다 이해해 주어서","mis":"K2-1-u7-X14"}],"mis":"K2-1-u7-X14","explanation":["언제나 고운 말이에요.","지도서 281쪽이에요.","유의 사항이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
