INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#21','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C7',3,'mc','auto','집에 가며 남자아이가 한 생각은?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":21,"concept":"K2-1-u7-C7","difficulty":3,"kind":"mc","stem":"집에 가며 남자아이가 한 생각은?","options":[{"t":"너무 화를 냈나 후회하고 친구가 다쳤을까 걱정했어요","correct":true},{"t":"더 크게 화낼 걸","mis":"K2-1-u7-X01"},{"t":"아무 생각 안 함","mis":"K2-1-u7-X01"}],"explanation":["되돌아봐요.","229쪽이에요.","지도서 294쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#22','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C10',3,'mc','auto','「슬금슬금」을 알맞게 넣은 문장은?',ARRAY['K2-1-u7-X10']::text[],false,'{"seq":22,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"「슬금슬금」을 알맞게 넣은 문장은?","options":[{"t":"「고양이가 생선 쪽으로 슬금슬금 다가갔다.」","correct":true},{"t":"「별이 슬금슬금 빛났다.」","mis":"K2-1-u7-X10"},{"t":"「아기가 슬금슬금 웃었다.」","mis":"K2-1-u7-X10"}],"explanation":["뜻에 맞아요.","236쪽이에요.","흉내 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#23','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C3',4,'sa','auto','지우가 얼마 전 잃어버린 물건을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u7-C3","difficulty":4,"kind":"sa","stem":"지우가 얼마 전 잃어버린 물건을 두 글자로 쓰세요.","answer":["우산"],"explanation":["우산이에요.","지도서 287쪽이에요.","듣기 자료예요."],"asset":{"type":"passage","lines":["지우는 승강기에서 토끼가 그려진 머리핀을 발견했어요.","얼마 전 아끼는 우산을 잃어버려 속상했던 지우는 주인을 찾아 주고 싶었어요.","관리 사무소 소장님께 말씀드리고 「머리핀 주인을 찾습니다!」 안내문을 만들었어요.","며칠 뒤 안내문에 고맙다는 쪽지가 붙어 있었어요. 지우는 뿌듯하고 행복했어요."],"title":"『국어』 220쪽 「지우와 머리핀」(듣기 자료) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#24','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C5',4,'essay','teacher','지난 주말에 겪은 일 가운데 가장 기억에 남는 일을 생각이나 느낌과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"지난 주말에 겪은 일 가운데 가장 기억에 남는 일을 생각이나 느낌과 함께 쓰세요.","answer_guide":{"answer":"예: 지난 일요일, 할머니 댁 텃밭에서 고구마를 캤다. 커다란 고구마가 나와서 정말 신기했다.","scoring_points":["기억에 남는 일을 썼어요","생각이나 느낌을 썼어요"]},"explanation":["발표 준비예요.","225쪽이에요.","정리하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#25','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C7',4,'essay','teacher','만화 속 두 친구가 사이좋게 지내려면 서로 어떻게 말하면 좋을지 남자아이와 여자아이의 말을 하나씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u7-C7","difficulty":4,"kind":"essay","stem":"만화 속 두 친구가 사이좋게 지내려면 서로 어떻게 말하면 좋을지 남자아이와 여자아이의 말을 하나씩 쓰세요.","answer_guide":{"answer":"예: 남자아이 — 「화내서 미안해.」 / 여자아이 — 「사과해 줘서 고마워. 나도 미안해.」","scoring_points":["남자아이의 고운 말을 썼어요","여자아이의 고운 말을 썼어요"]},"explanation":["화해의 말이에요.","229쪽이에요.","지도서 295쪽이에요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"너 때문에 그림을 망쳤잖아. 앞을 잘 보고 다녀야지."},{"who":"여자아이","text":"그림을 망쳐서 화가 많이 났구나. 미안해. 가방이 걸려 있는 줄 몰랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
