INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#19','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C9',3,'ox','auto','메기는 험상궂게 생겼으니 성격도 나쁠 것이다.',ARRAY['K2-1-u7-X02']::text[],false,'{"seq":19,"concept":"K2-1-u7-C9","difficulty":3,"kind":"ox","stem":"메기는 험상궂게 생겼으니 성격도 나쁠 것이다.","answer":"X","reason_options":[{"t":"메기는 다정하게 인사하고 친구를 도와준 따뜻한 친구라서","correct":true},{"t":"겉모습과 성격은 늘 같아서","mis":"K2-1-u7-X02"}],"mis":"K2-1-u7-X02","explanation":["겉모습만 보지 않아요.","233~235쪽이에요.","이야기예요."],"asset":{"type":"scene","icon":"🐟","text":"「메기야, 고마워」(홍은순) — 강이 넘쳐 연못에 온 메기를 피하던 물고기들이, 물장군을 쫓아 준 메기에게 고맙다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
