INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#21','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C8',3,'mc','auto','우산을 안 가져온 친구에게 알맞은 고운 말은?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":21,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"우산을 안 가져온 친구에게 알맞은 고운 말은?","options":[{"t":"「우산을 안 가져왔구나. 같이 쓰고 가자.」","correct":true},{"t":"「그러게 챙겼어야지.」","mis":"K2-1-u7-X01"},{"t":"「먼저 갈게.」","mis":"K2-1-u7-X01"}],"explanation":["함께해요.","국어활동 103쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#22','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C9',3,'mc','auto','메기가 연못에 와서 처음 한 말은?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":22,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"메기가 연못에 와서 처음 한 말은?","options":[{"t":"「안녕? 나는 메기란다. 앞으로 잘 지내자.」","correct":true},{"t":"「저리 비켜!」","mis":"K2-1-u7-X07"},{"t":"「여기는 내 연못이야.」","mis":"K2-1-u7-X07"}],"explanation":["인사했어요.","233쪽이에요.","메기의 말이에요."],"asset":{"type":"scene","icon":"🐟","text":"「메기야, 고마워」(홍은순) — 강이 넘쳐 연못에 온 메기를 피하던 물고기들이, 물장군을 쫓아 준 메기에게 고맙다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#23','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C9',4,'sa','auto','붕어와 잉어의 몸에 달라붙은 벌레 이름을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u7-C9","difficulty":4,"kind":"sa","stem":"붕어와 잉어의 몸에 달라붙은 벌레 이름을 세 글자로 쓰세요.","answer":["물장군"],"explanation":["물장군이에요.","234쪽이에요.","이야기예요."],"asset":{"type":"scene","icon":"🐟","text":"「메기야, 고마워」(홍은순) — 강이 넘쳐 연못에 온 메기를 피하던 물고기들이, 물장군을 쫓아 준 메기에게 고맙다고 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#24','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C4',4,'essay','teacher','지우의 경험과 비슷한 나의 경험을 「있었던 일」과 「생각이나 느낌」으로 나누어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u7-C4","difficulty":4,"kind":"essay","stem":"지우의 경험과 비슷한 나의 경험을 「있었던 일」과 「생각이나 느낌」으로 나누어 쓰세요.","answer_guide":{"answer":"예: 있었던 일 — 아끼는 모자를 잃어버렸다. / 느낌 — 속상해서 다음엔 이름을 써 두기로 했다.","scoring_points":["있었던 일을 썼어요","생각이나 느낌을 썼어요"]},"explanation":["경험 정리예요.","223쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#25','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C11',4,'essay','teacher','고운 말로 마음을 전하고 싶은 사람에게 쪽지를 쓰세요. (받을 사람, 마음과 까닭, 고운 말)','{}'::text[],false,'{"seq":25,"concept":"K2-1-u7-C11","difficulty":4,"kind":"essay","stem":"고운 말로 마음을 전하고 싶은 사람에게 쪽지를 쓰세요. (받을 사람, 마음과 까닭, 고운 말)","answer_guide":{"answer":"예: 담임 선생님께 — 모르는 것도 자세히 알려 주셔서 감사합니다. 선생님 덕분에 학교가 즐거워요.","scoring_points":["받을 사람을 썼어요","마음과 까닭을 고운 말로 썼어요"]},"explanation":["고운 말 쪽지예요.","239쪽이에요.","붙임 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#1','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C1',1,'mc','auto','무거운 책상을 옮기는 친구에게 하면 좋은 말은?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":1,"concept":"K2-1-u7-C1","difficulty":1,"kind":"mc","stem":"무거운 책상을 옮기는 친구에게 하면 좋은 말은?","options":[{"t":"「많이 무겁지? 내가 도와줄게.」","correct":true},{"t":"「그것도 못 옮기니?」","mis":"K2-1-u7-X01"},{"t":"「모르는 일이야.」","mis":"K2-1-u7-X01"}],"explanation":["도와줘요.","219쪽이에요.","예시예요."],"asset":{"type":"speech","turns":[{"who":"여자아이","text":"휴, 힘들어. 많이 무겁네."},{"who":"남자아이","text":"혼자서 그것도 못 옮기니?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#2','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C2',1,'mc','auto','웃어른께 사과드릴 때 하는 네 글자 고운 말은?',ARRAY['K2-1-u7-X09']::text[],false,'{"seq":2,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"웃어른께 사과드릴 때 하는 네 글자 고운 말은?","options":[{"t":"죄송해요","correct":true},{"t":"고마워요","mis":"K2-1-u7-X09"},{"t":"괜찮아요","mis":"K2-1-u7-X09"}],"explanation":["죄송해요예요.","지도서 292쪽이에요.","초성 퀴즈예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#3','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C3',1,'mc','auto','쪽지를 본 지우의 마음은?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"쪽지를 본 지우의 마음은?","options":[{"t":"뿌듯하고 행복한 마음","correct":true},{"t":"귀찮은 마음","mis":"K2-1-u7-X07"},{"t":"무서운 마음","mis":"K2-1-u7-X07"}],"explanation":["뿌듯해요.","223쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["지우는 승강기에서 토끼가 그려진 머리핀을 발견했어요.","얼마 전 아끼는 우산을 잃어버려 속상했던 지우는 주인을 찾아 주고 싶었어요.","관리 사무소 소장님께 말씀드리고 「머리핀 주인을 찾습니다!」 안내문을 만들었어요.","며칠 뒤 안내문에 고맙다는 쪽지가 붙어 있었어요. 지우는 뿌듯하고 행복했어요."],"title":"『국어』 220쪽 「지우와 머리핀」(듣기 자료) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
