INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#23','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C2',4,'sa','auto','다섯 글자이고 초성이 「ㄱㅁㅅㄴㄷ」인 고운 말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u7-C2","difficulty":4,"kind":"sa","stem":"다섯 글자이고 초성이 「ㄱㅁㅅㄴㄷ」인 고운 말을 쓰세요.","answer":["고맙습니다"],"explanation":["고맙습니다예요.","지도서 292쪽이에요.","초성 퀴즈예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#24','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C6',4,'essay','teacher','발표할 때 지킬 바른 자세 두 가지와 친구의 발표를 들을 때 지킬 점 한 가지를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u7-C6","difficulty":4,"kind":"essay","stem":"발표할 때 지킬 바른 자세 두 가지와 친구의 발표를 들을 때 지킬 점 한 가지를 쓰세요.","answer_guide":{"answer":"예: 듣는 사람을 바라본다. 말끝을 흐리지 않는다. / 끝까지 듣고 잘한 점을 칭찬한다.","scoring_points":["발표 자세 두 가지를 썼어요","듣는 자세를 썼어요"]},"explanation":["발표와 듣기예요.","227쪽이에요.","점검하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#25','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C12',4,'essay','teacher','지도서 313쪽 평가 — 「당신은 누구에게 어떤 고운 말을 자주 하나요?」와 「고운 말을 할 때 당신의 마음은 어떠한가요?」에 답하세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u7-C12","difficulty":4,"kind":"essay","stem":"지도서 313쪽 평가 — 「당신은 누구에게 어떤 고운 말을 자주 하나요?」와 「고운 말을 할 때 당신의 마음은 어떠한가요?」에 답하세요.","answer_guide":{"answer":"예: 동생에게 「잘했어!」라는 말을 자주 한다. / 그 말을 하면 나도 기분이 좋아진다.","scoring_points":["누구에게 어떤 고운 말을 하는지 썼어요","그때의 마음을 썼어요"]},"explanation":["자신 인터뷰예요.","지도서 313쪽이에요.","평가 자료 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
